export const ACTIVE_META_PALS = PALS.filter(pal => pal.isActiveRecommendation);
export const ACTIVE_META_PAL_IDS = ACTIVE_META_PALS.map(pal => pal.id);

export function getPalById(id) {
  return PALS.find(pal => [
    pal.id,
    pal.name,
    pal.canonicalId,
    ...(pal.legacyIds ?? []),
    ...(pal.aliases ?? []),
  ].includes(id)) ?? null;
}
